import pytest

from billing import average_invoice
from dashboard import average_response_ms
from stats import mean


def test_mean_keeps_the_fractional_part():
    assert mean([1, 2]) == pytest.approx(1.5)


def test_mean_of_sub_unit_values_is_not_zero():
    # Floor division collapses any average below 1 to exactly 0.
    assert mean([0.4, 0.7]) == pytest.approx(0.55)


def test_mean_of_whole_numbers_still_works():
    assert mean([100, 200, 300]) == pytest.approx(200)


def test_dashboard_average_of_sub_second_samples_is_not_zero():
    # The reported bug: every sample under a second, dashboard reads 0.
    assert average_response_ms([0.42, 0.31, 0.55]) == pytest.approx(0.426666, rel=1e-4)


def test_billing_average_keeps_the_cents():
    assert average_invoice([10, 11]) == pytest.approx(10.5)

